import os
import matplotlib.pyplot as plt
import numpy as np
import pandas as pd

import reader

from sklearn.metrics import (
    accuracy_score,
    confusion_matrix,
    ConfusionMatrixDisplay,
    roc_auc_score,
    RocCurveDisplay,
)
from sklearn.naive_bayes import GaussianNB

# Path constants
# Generated by LogisticRegression.py
TEST_IDS_FILE = "out/test_sample_ids.csv"
LABELS_FILE = "out/sample_labels.csv"


def prepare_data():
    expression, metadata = reader.load_data("../SRP092402")

    groups = ["tb subjects", "healthy controls"]

    metadata = metadata[metadata["refinebio_disease"].isin(groups)].copy()
    metadata = metadata.set_index("refinebio_accession_code")

    sample_ids = [sample for sample in expression.columns if sample in metadata.index]

    expression = expression[sample_ids]
    metadata = metadata.loc[sample_ids]

    expression = np.log2(expression + 1)

    labels = (metadata["refinebio_disease"] == "tb subjects").astype(int)

    # print("Expression matrix:", expression.shape)
    # print("Samples:", len(labels))

    # print("\nDisease groups:")
    # print(metadata["refinebio_disease"].value_counts())

    return expression, labels


def load_clusters(expression):
    sample_labels = pd.read_csv(LABELS_FILE).set_index("sample")

    clusters = sample_labels.loc[expression.columns, "cluster"]

    print("\nSize of Clusters:")
    print(clusters.value_counts().sort_index())

    return clusters


def rank_genes(model, genes):
    mean_0, mean_1 = model.theta_
    var_0, var_1 = model.var_

    # Weight each class variance by its degrees of freedom so the larger
    # class counts for more (disease is ~90/10)
    n_0, n_1 = model.class_count_
    pooled_var = ((n_0 - 1) * var_0 + (n_1 - 1) * var_1) / (n_0 + n_1 - 2)
    pooled_sd = np.sqrt(pooled_var)
    score = (mean_1 - mean_0) / pooled_sd

    ranking = pd.DataFrame(
        {"gene": genes, "score": score, "absolute_score": np.abs(score)}
    )

    return ranking.sort_values("absolute_score", ascending=False)


def train_model(expression, labels, n_genes, name, train_ids, test_ids):
    X = expression.T
    y = pd.Series(labels, index=X.index)

    X_train = X.loc[train_ids]
    X_test = X.loc[test_ids]
    y_train = y.loc[train_ids]
    y_test = y.loc[test_ids]

    gene_variance = X_train.var(axis=0)
    top_genes = gene_variance.nlargest(n_genes).index

    X_train = X_train[top_genes]
    X_test = X_test[top_genes]

    model = GaussianNB()

    model.fit(X_train, y_train)

    predictions = model.predict(X_test)
    probabilities = model.predict_proba(X_test)[:, 1]

    accuracy = accuracy_score(y_test, predictions)
    auc = roc_auc_score(y_test, probabilities)

    print(f"\n{name} - {n_genes} genes")
    print("Accuracy:", accuracy)
    print("AUC:", auc)

    prediction_results = pd.DataFrame(
        {
            "sample": X_test.index,
            "actual": y_test.values,
            "predicted": predictions,
            "probability": probabilities,
        }
    )

    prediction_results.to_csv(
        f"out/nb_{name}_{n_genes}_predictions.csv",
        index=False,
    )

    rank_genes(model, top_genes).to_csv(
        f"out/nb_{name}_{n_genes}_genes.csv",
        index=False,
    )

    RocCurveDisplay.from_predictions(
        y_test,
        probabilities,
    )

    plt.title(f"{name} Naive Bayes ({n_genes} genes)")
    plt.tight_layout()
    plt.savefig(
        f"out/nb_{name}_{n_genes}_roc.png",
        dpi=300,
    )
    plt.close()

    cm = confusion_matrix(
        y_test,
        predictions,
        labels=[0, 1],
    )

    display = ConfusionMatrixDisplay(
        confusion_matrix=cm,
        display_labels=["0", "1"],
    )

    display.plot(cmap="Blues")

    plt.title(f"{name} Naive Bayes ({n_genes} genes)")
    plt.tight_layout()
    plt.savefig(
        f"out/nb_{name}_{n_genes}_confusion.png",
        dpi=300,
    )
    plt.close()

    return {
        "Target": name,
        "Genes": n_genes,
        "Accuracy": accuracy,
        "AUC": auc,
    }


def main():
    os.makedirs("out", exist_ok=True)

    expression, disease_labels = prepare_data()

    clusters = load_clusters(expression)

    test_ids = pd.read_csv(TEST_IDS_FILE)["sample"].tolist()
    test_set = set(test_ids)
    train_ids = [sample for sample in expression.columns if sample not in test_set]

    print("Train Samples:", len(train_ids))
    print("Test Samples:", len(test_ids))

    results = []

    for n_genes in [5000, 10, 100, 1000, 10000]:
        results.append(
            train_model(
                expression,
                disease_labels,
                n_genes,
                "disease",
                train_ids,
                test_ids,
            )
        )

        results.append(
            train_model(
                expression,
                clusters,
                n_genes,
                "cluster",
                train_ids,
                test_ids,
            )
        )

    results = pd.DataFrame(results)

    results.to_csv("out/naive_bayes_model_summary.csv", index=False)

    print("\nNAIVE BAYES RESULTS")
    print(results.to_string(index=False))


if __name__ == "__main__":
    main()
